413→/**
414→ * Extract unique file paths that were changed during a session.
415→ * Looks at Write, Edit, and NotebookEdit tool calls.
416→ *
417→ * AC: @ui-session-stream ac-4 — Files changed during session.
418→ */
419→/**
420→ * Compute the distance from the bottom of a scroll container.
421→ * Used by SessionStream.svelte for auto-scroll detection.
422→ *
423→ * AC: @ui-session-stream ac-3
424→ */
425→export function computeScrollDistance(scrollHeight: number, scrollTop: number, clientHeight: number): number {
426→	return scrollHeight - scrollTop - clientHeight;
427→}
428→
429→/**
430→ * Determine whether auto-scroll should be active based on scroll position.
431→ * Returns true when the user is within the threshold of the bottom.
432→ *
433→ * AC: @ui-session-stream ac-3
434→ */
435→export const AUTO_SCROLL_THRESHOLD = 100;
436→
437→export function shouldAutoScroll(scrollHeight: number, scrollTop: number, clientHeight: number): boolean {
438→	return computeScrollDistance(scrollHeight, scrollTop, clientHeight) <= AUTO_SCROLL_THRESHOLD;
439→}
440→
441→/**
442→ * Determine whether the "jump to bottom" button should be visible.
443→ * Shown when not auto-scrolling AND there is content to jump to.
444→ *
445→ * AC: @ui-session-stream ac-3
446→ */
447→export function shouldShowJumpButton(autoScrolling: boolean, isLive: boolean, blockCount: number): boolean {
448→	return !autoScrolling && (isLive || blockCount > 0);
449→}
450→
451→/**
452→ * Accumulate streaming text from agent_text_chunk WebSocket events.
453→ * Only accumulates for the target session. Returns updated streaming text.
454→ *
455→ * AC: @ui-session-stream ac-2
456→ */
457→export function accumulateStreamingText(
458→	currentText: string,
459→	event: { event: string; data: unknown },
460→	targetSessionId: string,
461→): string {
462→	if (event.event !== 'agent_text_chunk') return currentText;
463→	const data = event.data as { session_id?: string; text?: string } | null;
464→	if (!data || data.session_id !== targetSessionId || !data.text) return currentText;
465→	return currentText + data.text;
466→}
467→
468→/**
469→ * Determine the last sequence number from an events array.
470→ * Returns -1 if the array is empty.
471→ *
472→ * AC: @ui-session-stream ac-2
473→ */
474→export function getLastSeq(events: Array<{ seq: number }>): number {
475→	if (events.length === 0) return -1;
476→	return events[events.length - 1].seq;
477→}
478→
479→const WRITE_TOOLS = new Set(['Write', 'Edit', 'NotebookEdit']);
480→
481→export function extractFilesChanged(blocks: DisplayBlock[]): string[] {
482→	const files = new Set<string>();
483→	for (const block of blocks) {
484→		if (block.type !== 'tool_call') continue;
485→		if (!WRITE_TOOLS.has(block.toolName)) continue;
486→		const input = block.input as Record<string, unknown> | null;
487→		if (!input) continue;
488→		const filePath = (input.file_path ?? input.notebook_path) as string | undefined;
489→		if (filePath) files.add(filePath);
490→	}
491→	return [...files].sort();
492→}
